      out.write("\n");
      out.write("        // Toggle Sidebar\n");
      out.write("        function toggleSidebar() {\n");
      out.write("            var sidebar = document.getElementById('sidebar');\n");
      out.write("            var mainWrapper = document.getElementById('mainWrapper');\n");
      out.write("            var backdrop = document.getElementById('sidebarBackdrop');\n");
      out.write("\n");
