      out.write("            }\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        function initTableData() {\n");
      out.write("            var tbody = document.getElementById('studentsTableBody');\n");
      out.write("            if (!tbody) return;\n");
      out.write("            allRows = Array.from(tbody.querySelectorAll('tr:not(#noDataRow)'));\n");
      out.write("            filteredRows = allRows.slice();\n");
      out.write("            currentPage = 1;\n");
      out.write("            renderTablePage();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Search filtering across all fields\n");
      out.write("        function handleSearch() {\n");
      out.write("            var query = document.getElementById('tableSearchInput').value.trim().toLowerCase();\n");
      out.write("\n");
      out.write("            if (!query) {\n");
      out.write("                filteredRows = allRows.slice();\n");
      out.write("            } else {\n");
      out.write("                filteredRows = allRows.filter(function(row) {\n");
      out.write("                    var text = (row.dataset.srno || '') + ' ' +\n");
      out.write("                               (row.dataset.name || '') + ' ' +\n");
      out.write("                               (row.dataset.email || '') + ' ' +\n");
      out.write("                               (row.dataset.mobile || '') + ' ' +\n");
      out.write("                               (row.dataset.college || '') + ' ' +\n");
      out.write("                               (row.dataset.stream || '') + ' ' +\n");
      out.write("                               (row.dataset.branch || '');\n");
      out.write("                    return text.toLowerCase().indexOf(query) !== -1;\n");
      out.write("                });\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            currentPage = 1;\n");
      out.write("            renderTablePage();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Change rows per page (5, 10, 25, 50, 100)\n");
      out.write("        function changeRowsPerPage() {\n");
      out.write("            var select = document.getElementById('rowsPerPageSelect');\n");
      out.write("            rowsPerPage = parseInt(select.value, 10) || 10;\n");
      out.write("            currentPage = 1;\n");
      out.write("            renderTablePage();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Render current page rows\n");
      out.write("        function renderTablePage() {\n");
      out.write("            var total = filteredRows.length;\n");
      out.write("            var totalPages = Math.ceil(total / rowsPerPage) || 1;\n");
      out.write("\n");
      out.write("            if (currentPage > totalPages) currentPage = totalPages;\n");
      out.write("            if (currentPage < 1) currentPage = 1;\n");
      out.write("\n");
      out.write("            var startIndex = (currentPage - 1) * rowsPerPage;\n");
      out.write("            var endIndex = Math.min(startIndex + rowsPerPage, total);\n");
      out.write("\n");
      out.write("            // Hide all rows first\n");
      out.write("            allRows.forEach(function(row) {\n");
      out.write("                row.style.display = 'none';\n");
      out.write("            });\n");
      out.write("\n");
      out.write("            // Show only rows for this page\n");
      out.write("            for (var i = startIndex; i < endIndex; i++) {\n");
      out.write("                if (filteredRows[i]) {\n");
      out.write("                    filteredRows[i].style.display = '';\n");
      out.write("                    // sync checkbox state\n");
      out.write("                    var cb = filteredRows[i].querySelector('.row-select-checkbox');\n");
      out.write("                    if (cb) {\n");
      out.write("                        cb.checked = selectedUserIds.has(cb.value);\n");
      out.write("                        if (cb.checked) {\n");
      out.write("                            filteredRows[i].classList.add('row-selected');\n");
      out.write("                        } else {\n");
      out.write("                            filteredRows[i].classList.remove('row-selected');\n");
      out.write("                        }\n");
      out.write("                    }\n");
      out.write("                }\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            // Empty state check\n");
      out.write("            var noDataRow = document.getElementById('noDataRow');\n");
      out.write("            if (total === 0) {\n");
      out.write("                if (!noDataRow) {\n");
      out.write("                    var tbody = document.getElementById('studentsTableBody');\n");
      out.write("                    var tr = document.createElement('tr');\n");
      out.write("                    tr.id = 'noDataRow';\n");
      out.write("                    tr.innerHTML = '<td colspan=\"9\" class=\"empty-row-td\">No matching student records found.</td>';\n");
      out.write("                    tbody.appendChild(tr);\n");
      out.write("                } else {\n");
      out.write("                    noDataRow.style.display = '';\n");
      out.write("                }\n");
      out.write("            } else if (noDataRow) {\n");
      out.write("                noDataRow.style.display = 'none';\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            // Update entries info text: \"Showing 1 to 10 of 25 entries\"\n");
      out.write("            var infoText = total === 0 ? \"Showing 0 to 0 of 0 entries\" :\n");
      out.write("                           \"Showing \" + (startIndex + 1) + \" to \" + endIndex + \" of \" + total + \" entries\";\n");
      out.write("            document.getElementById('entriesInfo').textContent = infoText;\n");
      out.write("\n");
      out.write("            // Render pagination buttons\n");
      out.write("            renderPaginationControls(totalPages);\n");
      out.write("\n");
      out.write("            // Update master select all checkbox state\n");
      out.write("            syncSelectAllCheckbox();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Render pagination buttons\n");
      out.write("        function renderPaginationControls(totalPages) {\n");
      out.write("            var container = document.getElementById('paginationControls');\n");
      out.write("            container.innerHTML = '';\n");
      out.write("\n");
      out.write("            // Previous Button\n");
      out.write("            var prevBtn = document.createElement('button');\n");
      out.write("            prevBtn.className = 'page-btn';\n");
      out.write("            prevBtn.textContent = 'Previous';\n");
      out.write("            prevBtn.disabled = (currentPage === 1);\n");
      out.write("            prevBtn.onclick = function() {\n");
      out.write("                if (currentPage > 1) {\n");
      out.write("                    currentPage--;\n");
      out.write("                    renderTablePage();\n");
      out.write("                }\n");
      out.write("            };\n");
      out.write("            container.appendChild(prevBtn);\n");
      out.write("\n");
      out.write("            // Page numbers\n");
      out.write("            var maxButtons = 5;\n");
      out.write("            var startPage = Math.max(1, currentPage - Math.floor(maxButtons / 2));\n");
      out.write("            var endPage = Math.min(totalPages, startPage + maxButtons - 1);\n");
      out.write("            if (endPage - startPage + 1 < maxButtons) {\n");
      out.write("                startPage = Math.max(1, endPage - maxButtons + 1);\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            for (var p = startPage; p <= endPage; p++) {\n");
      out.write("                (function(pageNumber) {\n");
      out.write("                    var pageBtn = document.createElement('button');\n");
      out.write("                    pageBtn.className = 'page-btn' + (pageNumber === currentPage ? ' active' : '');\n");
      out.write("                    pageBtn.textContent = pageNumber;\n");
      out.write("                    pageBtn.onclick = function() {\n");
      out.write("                        currentPage = pageNumber;\n");
      out.write("                        renderTablePage();\n");
      out.write("                    };\n");
      out.write("                    container.appendChild(pageBtn);\n");
      out.write("                })(p);\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            // Next Button\n");
      out.write("            var nextBtn = document.createElement('button');\n");
      out.write("            nextBtn.className = 'page-btn';\n");
      out.write("            nextBtn.textContent = 'Next';\n");
      out.write("            nextBtn.disabled = (currentPage === totalPages || totalPages === 0);\n");
      out.write("            nextBtn.onclick = function() {\n");
      out.write("                if (currentPage < totalPages) {\n");
      out.write("                    currentPage++;\n");
      out.write("                    renderTablePage();\n");
      out.write("                }\n");
      out.write("            };\n");
      out.write("            container.appendChild(nextBtn);\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Row checkbox toggle\n");
      out.write("        function handleRowSelect(cb) {\n");
      out.write("            var row = cb.closest('tr');\n");
      out.write("            if (cb.checked) {\n");
      out.write("                selectedUserIds.add(cb.value);\n");
      out.write("                if (row) row.classList.add('row-selected');\n");
      out.write("            } else {\n");
      out.write("                selectedUserIds.delete(cb.value);\n");
      out.write("                if (row) row.classList.remove('row-selected');\n");
      out.write("            }\n");
      out.write("            updateSelectedBadge();\n");
      out.write("            syncSelectAllCheckbox();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Master Select All checkbox\n");
      out.write("        function toggleSelectAll(masterCb) {\n");
      out.write("            var isChecked = masterCb.checked;\n");
      out.write("            // Apply to all currently visible rows in this page\n");
      out.write("            var startIndex = (currentPage - 1) * rowsPerPage;\n");
      out.write("            var endIndex = Math.min(startIndex + rowsPerPage, filteredRows.length);\n");
      out.write("\n");
      out.write("            for (var i = startIndex; i < endIndex; i++) {\n");
      out.write("                var row = filteredRows[i];\n");
      out.write("                var cb = row.querySelector('.row-select-checkbox');\n");
      out.write("                if (cb) {\n");
      out.write("                    cb.checked = isChecked;\n");
      out.write("                    if (isChecked) {\n");
      out.write("                        selectedUserIds.add(cb.value);\n");
      out.write("                        row.classList.add('row-selected');\n");
      out.write("                    } else {\n");
      out.write("                        selectedUserIds.delete(cb.value);\n");
      out.write("                        row.classList.remove('row-selected');\n");
      out.write("                    }\n");
      out.write("                }\n");
      out.write("            }\n");
      out.write("            updateSelectedBadge();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        function syncSelectAllCheckbox() {\n");
      out.write("            var masterCb = document.getElementById('selectAllCheckbox');\n");
      out.write("            if (!masterCb) return;\n");
      out.write("\n");
      out.write("            var startIndex = (currentPage - 1) * rowsPerPage;\n");
      out.write("            var endIndex = Math.min(startIndex + rowsPerPage, filteredRows.length);\n");
      out.write("            var visibleCount = endIndex - startIndex;\n");
      out.write("\n");
      out.write("            if (visibleCount === 0) {\n");
      out.write("                masterCb.checked = false;\n");
      out.write("                masterCb.indeterminate = false;\n");
      out.write("                return;\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            var checkedCount = 0;\n");
      out.write("            for (var i = startIndex; i < endIndex; i++) {\n");
      out.write("                var cb = filteredRows[i].querySelector('.row-select-checkbox');\n");
      out.write("                if (cb && cb.checked) {\n");
      out.write("                    checkedCount++;\n");
      out.write("                }\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            masterCb.checked = (checkedCount === visibleCount && visibleCount > 0);\n");
      out.write("            masterCb.indeterminate = (checkedCount > 0 && checkedCount < visibleCount);\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        function updateSelectedBadge() {\n");
      out.write("            var badge = document.getElementById('selectedCountBadge');\n");
      out.write("            var count = selectedUserIds.size;\n");
      out.write("            if (count > 0) {\n");
