      out.write("                badge.style.display = 'inline-block';\n");
      out.write("            } else {\n");
      out.write("                badge.style.display = 'none';\n");
      out.write("            }\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // ================= DELETE WITH STANDARD CHROME POPUP =================\n");
